-- Move organizations, users and memberships to better-auth's tables (created in 0002), then drop
-- the old ones. Generated by drizzle-kit, then reordered by hand: the generated order dropped
-- tables with CASCADE before dropping their foreign keys, which then no longer existed.
--
-- Existing CI tokens can't be carried over (better-auth stores keys in its own format), so after
-- this migration every project needs `circi admin project rotate-token`.

-- 1. Copy existing rows into better-auth's tables.
INSERT INTO "organization" ("id", "name", "slug", "created_at")
SELECT "id"::text, "name", "slug", "created_at" FROM "organizations";--> statement-breakpoint
INSERT INTO "user" ("id", "name", "email", "email_verified", "created_at", "updated_at")
SELECT "id"::text, coalesce("name", "email"), lower("email"), false, "created_at", "created_at" FROM "users";--> statement-breakpoint
INSERT INTO "member" ("id", "organization_id", "user_id", "role", "created_at")
SELECT gen_random_uuid()::text, "org_id"::text, "user_id"::text,
  CASE WHEN "role" = 'viewer' THEN 'member' ELSE "role" END, "created_at"
FROM "memberships";--> statement-breakpoint

-- 2. Detach projects and reviews from the old tables.
ALTER TABLE "projects" DROP CONSTRAINT "projects_org_id_organizations_id_fk";--> statement-breakpoint
ALTER TABLE "reviews" DROP CONSTRAINT "reviews_user_id_users_id_fk";--> statement-breakpoint
ALTER TABLE "projects" DROP CONSTRAINT "projects_token_hash_unique";--> statement-breakpoint
ALTER TABLE "projects" DROP COLUMN "token_hash";--> statement-breakpoint
ALTER TABLE "projects" DROP COLUMN "token_hint";--> statement-breakpoint
ALTER TABLE "projects" DROP COLUMN "token_created_at";--> statement-breakpoint

-- 3. better-auth ids are text.
ALTER TABLE "projects" ALTER COLUMN "org_id" SET DATA TYPE text;--> statement-breakpoint
ALTER TABLE "reviews" ALTER COLUMN "user_id" SET DATA TYPE text;--> statement-breakpoint
ALTER TABLE "projects" ADD CONSTRAINT "projects_org_id_organization_id_fk" FOREIGN KEY ("org_id") REFERENCES "public"."organization"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint

-- 4. Drop the old tables.
DROP TABLE "memberships";--> statement-breakpoint
DROP TABLE "organizations";--> statement-breakpoint
DROP TABLE "users";
